-- UPDATE: correct balance table depWL
DECLARE @Custid INT, @Winlostdate SMALLDATETIME
DECLARE @count INT = 1
WHILE (1 = 1)
BEGIN
	
	SELECT TOP 1 @Custid = CustId  FROM #DiffData WHERE Isfinished = 0

	IF @@ROWCOUNT = 0
		BREAK
	
	UPDATE a 
	SET a.ClosingBalance = b.ClosingBalance,
		a.OpeningBalance = b.OpeningBalance,
		a.Deposit = b.Deposit
	FROM rptDepWinlost_bk a WITH(ROWLOCK) INNER JOIN rptDepWinlost_bk_20240425 b (NOLOCK) ON a.winlostdate = b.winlostdate AND a.custid = b.custid 
	WHERE a.custid = @Custid 

	UPDATE a 
	SET a.OpeningBalance = b.OpeningBalance
	FROM rptDepWinlost_Main a WITH(ROWLOCK) INNER JOIN rptDepWinlost_Main_20240425 b (NOLOCK) ON a.winlostdate = b.winlostdate AND a.custid = b.custid
	WHERE a.custid = @Custid 
	
	UPDATE #DiffData SET Isfinished = 1 WHERE CustId = @Custid
END

GO

